SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS users (id CHAR(36) PRIMARY KEY,login VARCHAR(32) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,display_name VARCHAR(120) NOT NULL,role VARCHAR(32) NOT NULL DEFAULT 'warehouse',active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL,last_login DATETIME NULL,version INT UNSIGNED NOT NULL DEFAULT 1,deleted_at DATETIME NULL,INDEX(active,deleted_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS sessions (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,created_at DATETIME NOT NULL,expires_at DATETIME NOT NULL,revoked_at DATETIME NULL,FOREIGN KEY(user_id) REFERENCES users(id),INDEX(token_hash,expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS vehicles (id CHAR(36) PRIMARY KEY,number VARCHAR(40) NOT NULL,driver VARCHAR(120) NOT NULL DEFAULT '',delivery_number VARCHAR(80) NOT NULL DEFAULT '',expected_date DATE NULL,status VARCHAR(64) NOT NULL,created_at DATETIME NOT NULL,created_by CHAR(36) NOT NULL,unloaded_at DATETIME NULL,version INT UNSIGNED NOT NULL DEFAULT 1,deleted_at DATETIME NULL,FOREIGN KEY(created_by) REFERENCES users(id),INDEX(number),INDEX(status,expected_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS deliveries (id CHAR(36) PRIMARY KEY,number VARCHAR(80) NOT NULL UNIQUE,vehicle_id CHAR(36) NULL,created_at DATETIME NOT NULL,created_by CHAR(36) NOT NULL,version INT UNSIGNED NOT NULL DEFAULT 1,deleted_at DATETIME NULL,FOREIGN KEY(vehicle_id) REFERENCES vehicles(id),FOREIGN KEY(created_by) REFERENCES users(id),INDEX(vehicle_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS prns (id CHAR(36) PRIMARY KEY,number VARCHAR(80) NOT NULL UNIQUE,delivery_id CHAR(36) NOT NULL,reception_started_at DATETIME NULL,ready_at DATETIME NULL,closed_at DATETIME NULL,created_at DATETIME NOT NULL,created_by CHAR(36) NOT NULL,version INT UNSIGNED NOT NULL DEFAULT 1,deleted_at DATETIME NULL,FOREIGN KEY(delivery_id) REFERENCES deliveries(id),FOREIGN KEY(created_by) REFERENCES users(id),INDEX(delivery_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS prn_items (id CHAR(36) PRIMARY KEY,prn_id CHAR(36) NOT NULL,name VARCHAR(255) NOT NULL,planned INT UNSIGNED NOT NULL,received INT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,version INT UNSIGNED NOT NULL DEFAULT 1,deleted_at DATETIME NULL,FOREIGN KEY(prn_id) REFERENCES prns(id),INDEX(prn_id),INDEX(name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cells (id CHAR(36) PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,description VARCHAR(255) NOT NULL DEFAULT '',created_at DATETIME NOT NULL,created_by CHAR(36) NOT NULL,version INT UNSIGNED NOT NULL DEFAULT 1,deleted_at DATETIME NULL,FOREIGN KEY(created_by) REFERENCES users(id),INDEX(name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS pallets (id CHAR(36) PRIMARY KEY,number VARCHAR(32) NOT NULL UNIQUE,prn_id CHAR(36) NOT NULL,status VARCHAR(32) NOT NULL,cell_id CHAR(36) NULL,created_at DATETIME NOT NULL,created_by CHAR(36) NOT NULL,completed_at DATETIME NULL,placed_at DATETIME NULL,version INT UNSIGNED NOT NULL DEFAULT 1,deleted_at DATETIME NULL,FOREIGN KEY(prn_id) REFERENCES prns(id),FOREIGN KEY(cell_id) REFERENCES cells(id),FOREIGN KEY(created_by) REFERENCES users(id),INDEX(prn_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS pallet_items (id CHAR(36) PRIMARY KEY,pallet_id CHAR(36) NOT NULL,prn_item_id CHAR(36) NOT NULL,quantity INT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,deleted_at DATETIME NULL,FOREIGN KEY(pallet_id) REFERENCES pallets(id),FOREIGN KEY(prn_item_id) REFERENCES prn_items(id),UNIQUE(pallet_id,prn_item_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS stock (id CHAR(36) PRIMARY KEY,cell_id CHAR(36) NOT NULL,prn_item_id CHAR(36) NOT NULL,quantity INT UNSIGNED NOT NULL,updated_at DATETIME NOT NULL,version INT UNSIGNED NOT NULL DEFAULT 1,FOREIGN KEY(cell_id) REFERENCES cells(id),FOREIGN KEY(prn_item_id) REFERENCES prn_items(id),UNIQUE(cell_id,prn_item_id),INDEX(prn_item_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS placements (id CHAR(36) PRIMARY KEY,prn_id CHAR(36) NOT NULL,prn_item_id CHAR(36) NOT NULL,pallet_id CHAR(36) NULL,cell_id CHAR(36) NOT NULL,quantity INT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,created_by CHAR(36) NOT NULL,FOREIGN KEY(prn_id) REFERENCES prns(id),FOREIGN KEY(prn_item_id) REFERENCES prn_items(id),FOREIGN KEY(pallet_id) REFERENCES pallets(id),FOREIGN KEY(cell_id) REFERENCES cells(id),FOREIGN KEY(created_by) REFERENCES users(id),INDEX(prn_id),INDEX(prn_item_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS audit_log (id CHAR(36) PRIMARY KEY,created_at DATETIME NOT NULL,user_id CHAR(36) NOT NULL,user_name VARCHAR(120) NOT NULL,action VARCHAR(64) NOT NULL,entity VARCHAR(64) NOT NULL,entity_id CHAR(36) NOT NULL,old_value JSON NULL,new_value JSON NULL,INDEX(entity_id),INDEX(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS settings (`key` VARCHAR(64) PRIMARY KEY,`value` VARCHAR(255) NOT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
